test('M14 complete reverse byte projection retains every helper callback assertion member template and order', () => {
  assert.equal(projected.split(begin).length, 2); assert.equal(projected.split(end).length, 2);
  const body = projected.split(begin)[1].split(end)[0];
  assert.equal(reverseBareRegistrations(body), removeApplicationImports(erased));
  const tree = parse(body); const registrations = tree.statements.filter(n => ts.isExpressionStatement(n) && ts.isCallExpression(n.expression) && n.expression.expression.getText(tree) === 'control');
  assert.equal(registrations.length, 5);
  assert.deepEqual(registrations.map(n => n.expression.arguments[0].text), parse(erased).statements.filter(n => ts.isExpressionStatement(n) && ts.isCallExpression(n.expression) && n.expression.expression.getText() === 'test').map(n => n.expression.arguments[0].text));
});
test('M15 exact source closure pins preserve class constants and pure helper authority', () => {
  const pins = { 'src/lib/resource-cache.ts': 'd8ffefde0b8b2449b9c038e9547a330ffe7dc060dcb9a410c97696e08382bbb9', 'src/lib/cluster-response.ts': 'e64a9e7ea57e98b4af22e6eda30925c5e81d6d9a9cfbd5e12140c1c0405983bd', 'src/lib/cluster-metadata.ts': '4ad9462cc00380744b9680c6aa1e7315bd50553cd9988faf491ae65711fee24a' };
  assert.equal(digest(original), row.sha256);
  for (const [path, hash] of Object.entries(pins)) assert.equal(digest(read(path)), hash, path);
});
test('M16 selected-copy infrastructure prefix is pinned and imports no application modules', () => {
  const prefix = projected.split(begin)[0]; assert.equal(digest(prefix), '12f9f6b076a632caea56468e446e9a4db375ee70ca3ac12f3715b2531205c48c');
  const ast = parse(prefix);
  assert.deepEqual(ast.statements.filter(n => ts.isImportDeclaration(n)).map(n => n.moduleSpecifier.text), ['node:fs', 'node:module', 'node:crypto', 'node:vm']);
  assert.ok(prefix.includes("useDefineForClassFields: true")); assert.ok(prefix.includes('{ timeout: 1000 }'));
  assert.equal(prefix.includes("declaration(responseAST, 'clusterMissing')"), false);
});
test('M17 historical failure and unqualified full-suite scope remain literal', () => {
  assert.ok(plan.scope.includes('Historical 7911/7841/70')); assert.ok(plan.scope.includes('not a suite pass'));
  assert.ok(plan.discovered.includes(row.original)); assert.equal(plan.retainedUnmapped.includes(row.original), false); assert.ok(plan.selected.includes(row.current));
});
